CREATE TABLE `user` (id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(100) NOT NULL,real_name VARCHAR(50),phone VARCHAR(20),email VARCHAR(100),role INTEGER DEFAULT 0,status INTEGER DEFAULT 1,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,update_time DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE camera(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),location VARCHAR(200),ip_address VARCHAR(50),rtsp_url VARCHAR(1000),status INTEGER DEFAULT 1,fault_type VARCHAR(50),longitude DOUBLE,latitude DOUBLE,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,update_time DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE abnormal_event(id BIGINT AUTO_INCREMENT PRIMARY KEY,camera_id BIGINT NOT NULL,event_time DATETIME NOT NULL,location VARCHAR(200) NOT NULL,level INTEGER NOT NULL,type VARCHAR(50),status INTEGER DEFAULT 0,image_url VARCHAR(500),description TEXT,handler_id BIGINT,handle_time DATETIME,handle_result TEXT,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,update_time DATETIME DEFAULT CURRENT_TIMESTAMP);
